class OutputParser:
    def parse_and_validate_l3(self, llm_output: str) -> Dict:
        """
        Parse LLM output and validate against schema.
        Returns validated dict or raises exception.
        """
        # Step 1: Extract JSON from response
        try:
            # Try direct parse first
            parsed = json.loads(llm_output)
        except json.JSONDecodeError:
            # LLM might have wrapped in markdown code block
            parsed = self._extract_json_from_markdown(llm_output)

        # Step 2: Schema validation
        try:
            validate(instance=parsed, schema=L3_SCHEMA)
        except ValidationError as e:
            raise ValueError(f"Schema validation failed: {e.message}")

        # Step 3: Business logic validation
        self._validate_business_rules_l3(parsed)

        return parsed

    def _extract_json_from_markdown(self, text: str) -> Dict:
        """Extract JSON from ```json ... ``` blocks"""
        import re
        match = re.search(r'```json\s*(\{.*?\})\s*```', text, re.DOTALL)
        if match:
            return json.loads(match.group(1))
        raise ValueError("No valid JSON found in LLM output")

    def _validate_business_rules_l3(self, data: Dict):
        """Additional validation beyond schema"""
        # Rule: No duplicate cluster names
        names = [c['name'] for c in data['interest_clusters']]
        if len(names) != len(set(names)):
            raise ValueError("Duplicate cluster names detected")

        # Rule: Clusters must have confidence >0.65
        for cluster in data['interest_clusters']:
            if cluster['confidence'] < 0.65:
                raise ValueError(f"Cluster {cluster['name']} below minimum confidence")

        # Rule: Emerging interests must be distinct from clusters
        emerging_names = [e['name'] for e in data['emerging_interests']]
        if set(emerging_names) & set(names):
            raise ValueError("Emerging interest already exists as cluster")
