        self, 
        user_id: str, 
        layer: Layer, 
        batch_data: Dict
    ) -> Dict:
        """
        Generate layer update with automatic retry on transient failures.
        """
        try:
            # Call LLM API
            response = await self.llm_client.chat_completion(
                model=self._get_model_for_layer(layer),
                messages=self._build_prompt(layer, batch_data),
                temperature=0.3,  # Low temp for consistency
                max_tokens=1500,
                timeout=30.0
            )

            # Parse and validate
            parsed = self.parser.parse_and_validate(
                layer, 
                response.choices[0].message.content
            )

            # PII scan
