                raise PIIDetectedError(f"PII found in layer {layer} for user {user_id}")

            return parsed

        except (TimeoutError, json.JSONDecodeError) as e:
            # Retryable errors - tenacity will retry
            self.metrics.increment(f"llm.{layer}.retry", tags=["error:transient"])
            raise

        except (ValidationError, PIIDetectedError) as e:
            # Non-retryable errors - fail immediately
            self.metrics.increment(f"llm.{layer}.failure", tags=["error:validation"])
            await self.alert_service.send(
                channel="profile-errors",
                severity="high",
                message=f"Layer {layer} generation failed for user {user_id}: {e}"
            )
            raise

